add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_disable_gateway_by_cart_total' );

function perfectpixel_disable_gateway_by_cart_total( $gateways ) {
	if ( is_admin() || ! WC()->cart ) {
		return $gateways;
	}
	// Gateway ID => [ minimum total, maximum total ] (0 = no limit). The gateway is shown only inside the range.
	$rules = array(
		'cod'  => array( 0, 500 ),
		'bacs' => array( 10, 0 ),
	);

	$total = (float) WC()->cart->get_total( 'edit' );
	foreach ( $rules as $id => $range ) {
		list( $min, $max ) = $range;
		if ( ( $min > 0 && $total < $min ) || ( $max > 0 && $total > $max ) ) {
			unset( $gateways[ $id ] );
		}
	}
	return $gateways;
}
